def a(n):
    if n == 1:
        return 10
    prev_a = a(n-1)
    # a_n = 6*a_{n-1} - 2^(n+1) - 3^n + 5
    return 6*prev_a - (2**(n+1)) - (3**n) + 5

for i in range(1, 11):
    print(f"a_{i} = {a(i)}")
    print(f"a_{i} mod 2 = {a(i) % 2}")
    print(f"a_{i} mod 3 = {a(i) % 3}")

